class Solution { public:vector<long long> kthPalindrome(vector<int>& queries,int intLength){int halfLength=(intLength+1)/2;long long start=1;for(int i=1;i<halfLength;++i)start*=10;long long limit=9*start;vector<long long> answer;for(int query:queries){long long offset=query-1;if(offset>=limit){answer.push_back(-1);continue;}long long half=start+offset,result=half,mirror=intLength%2?half/10:half;while(mirror){result=result*10+mirror%10;mirror/=10;}answer.push_back(result);}return answer;} };
